// Render user-friendly status without losing fault information.
context.handlebars.registerHelper('healthLabel', (v) => {
  if (v === true || v === 'true') return 'Working';
  if (v === false || v === 'false') return 'Fault';
  return 'Unknown';
});
context.handlebars.registerHelper('alarmLabel', (v) => {
  if (v === true || v === 'true') return 'Acknowledged';
  if (v === false || v === 'false') return 'Not acknowledged';
  return 'Unknown';
});
context.handlebars.registerHelper('buzzerLabel', (v) => {
  if (v === true || v === 'true') return 'Enabled';
  if (v === false || v === 'false') return 'Disabled';
  return 'Unknown';
});
context.handlebars.registerHelper('overallLabel', (v) => {
  if (v === 'OK') return 'All sensors working';
  if (v === 'FAULT') return 'Sensor fault detected';
  return v || 'Unknown';
});
context.handlebars.registerHelper('faultLabel', (v) => {
  if (v === 'NONE') return 'None';
  if (v === 'DHT_INVALID') return 'Temperature / humidity sensor';
  if (v === 'MPU_INVALID') return 'Vibration sensor';
  return v || 'Unknown';
});
context.handlebars.registerHelper('conditionColor', (v) => {
  if (v === 'CRITICAL') return '#f87171';
  if (v === 'WARNING') return '#fbbf24';
  if (v === 'NORMAL') return '#4ade80';
  return '#cbd5e1';
});

// Handle MQTT nested JSON objects whether the datasource provides an object
// or a JSON string. Never substitute default thresholds for missing live data.
context.handlebars.registerHelper('threshold', (raw, key) => {
  let obj = raw;
  if (typeof obj === 'string') {
    try { obj = JSON.parse(obj); } catch (_) { return '—'; }
  }
  if (!obj || typeof obj !== 'object') return '—';
  const value = obj[key];
  return value === undefined || value === null || value === '' ? '—' : String(value);
});
context.handlebars.registerHelper('monitorMode', (raw) => {
  let obj = raw;
  if (typeof obj === 'string') {
    try { obj = JSON.parse(obj); } catch (_) { return '—'; }
  }
  if (!obj || typeof obj !== 'object') return '—';
  return obj.low_enabled === true ? 'Low + high' : obj.low_enabled === false ? 'High only' : '—';
});

