const form = Object.fromEntries(context.panel.elements.map(e=>[e.id,e.value]));
(async () => {
  try {
    const r = await fetch('http://localhost:5001/api/session', {
      method:'POST',credentials:'include',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({username:form.username,password:form.password})
    });
    const body = await r.json();
    context.panel.patchFormValue({password:''});
    if (!r.ok || !body.authenticated) throw new Error(body.error||'Login refused');
    context.grafana.notifySuccess(['Operator access','Signed in for 30 minutes']);
    context.grafana.refresh();
  } catch(err) {
    context.grafana.notifyError(['Operator login failed',String(err.message||err)]);
  }
})();

