const api = 'http://localhost:5001';
const state = Object.fromEntries(context.panel.elements.map(e => [e.id,e.value]));
const send = async (path, data) => {
  const sessionResp = await fetch(api + '/api/session', {credentials:'include'});
  if (!sessionResp.ok) throw new Error('Sign in using the Operator Access panel first.');
  const auth = await sessionResp.json();
  if (!auth.authenticated || !auth.csrf) throw new Error('Sign in as operator first');
  const reply = await fetch(api + path, {
    method:'POST', credentials:'include',
    headers:{'Content-Type':'application/json','X-CSRF-Token':auth.csrf},
    body:JSON.stringify(data)
  });
  const result = await reply.json();
  if (!reply.ok || result.status !== 'APPLIED') {
    throw new Error(result.reason || result.error || 'ESP32 did not confirm the command');
  }
  context.grafana.notifySuccess(['ESP32 confirmed', result.reason || 'APPLIED']);
  context.grafana.refresh();
  return result;
};

(async () => {
  try { await send('/api/config', {metric:"temperature",critical_low:Number(state["critical_low"]),warning_low:Number(state["warning_low"]),warning_high:Number(state["warning_high"]),critical_high:Number(state["critical_high"])}); }
  catch(err) { context.grafana.notifyError(['Command NOT applied', String(err.message || err)]); }
})();

